let pdfDiagnosticThrottleAt = 0;

function attachPdfDiagnostics() {
  if (typeof window === 'undefined' || typeof window.addEventListener !== 'function') {
    return;
  }

  window.addEventListener(PDF_DIAGNOSTIC_EVENT, (event) => {
    const now = Date.now();
    if (now - pdfDiagnosticThrottleAt < PDF_DIAGNOSTIC_THROTTLE_MS) {
      return;
    }
    pdfDiagnosticThrottleAt = now;

    const detail = event && event.detail && typeof event.detail === 'object' ? event.detail : {};
    const entry = {
      prefix: VIEWER_LOG_PREFIX_DEEP,
      step: normalizeValue(detail.step),
      details: detail.details && typeof detail.details === 'object'
        ? detail.details
        : (detail.details ?? ''),
      source: 'pdfjs',
      isViewerOpen: Boolean(elements && elements.viewer && !elements.viewer.hidden),
      activeFile: viewerTabsState && viewerTabsState.activeFile ? (viewerTabsState.activeFile.name || '') : '',
    };

    sendPdfLogEntry(entry.prefix, entry.step, entry);
    logClientEvent('task_view_pdf_diagnostics', entry, { keepalive: true });
  });
}

function collectResponseHeaders(response) {
  if (!response || !response.headers || typeof response.headers.get !== 'function') {
    return {};
  }

  const names = [
    'content-type',
    'content-length',
    'content-disposition',
    'cache-control',
    'etag',
    'last-modified',
    'age',
    'server-timing',
    'cf-cache-status',
    'x-cache',
    'x-served-by',
    'via',
    'pragma',
    'expires',
    'accept-ranges',
    'content-range',
    'x-frame-options',
    'content-security-policy',
    'x-content-type-options',
  ];
  const result = {};
  names.forEach((name) => {
    const value = response.headers.get(name);
    if (value) {
      result[name] = value;
    }
  });
  return result;
}

function getFetchResourceTimingSample(targetUrl) {
  if (typeof performance === 'undefined' || !performance || typeof performance.getEntriesByType !== 'function') {
    return null;
  }

  const normalizedUrl = normalizeValue(targetUrl);
  if (!normalizedUrl) {
    return null;
  }

  try {
    const entries = performance.getEntriesByType('resource');
    if (!Array.isArray(entries) || entries.length === 0) {
      return null;
    }

    for (let index = entries.length - 1; index >= 0; index -= 1) {
      const entry = entries[index];
      if (!entry || typeof entry.name !== 'string') {
        continue;
      }
      if (entry.name !== normalizedUrl) {
        continue;
      }

      const protocol = typeof entry.nextHopProtocol === 'string' ? entry.nextHopProtocol : '';
      const dnsMs = entry.domainLookupEnd > 0 && entry.domainLookupStart > 0
        ? Math.max(0, entry.domainLookupEnd - entry.domainLookupStart)
        : 0;
      const tcpMs = entry.connectEnd > 0 && entry.connectStart > 0
        ? Math.max(0, entry.connectEnd - entry.connectStart)
        : 0;
      const tlsMs = entry.connectEnd > 0 && entry.secureConnectionStart > 0
        ? Math.max(0, entry.connectEnd - entry.secureConnectionStart)
        : 0;
      const ttfbMs = entry.responseStart > 0 && entry.requestStart > 0
        ? Math.max(0, entry.responseStart - entry.requestStart)
        : 0;
      const downloadMs = entry.responseEnd > 0 && entry.responseStart > 0
        ? Math.max(0, entry.responseEnd - entry.responseStart)
        : 0;
      const totalMs = entry.duration > 0 ? Math.max(0, entry.duration) : 0;

      return {
        initiatorType: normalizeValue(entry.initiatorType),
        transferSize: Number.isFinite(entry.transferSize) ? Math.round(entry.transferSize) : 0,
        encodedBodySize: Number.isFinite(entry.encodedBodySize) ? Math.round(entry.encodedBodySize) : 0,
        decodedBodySize: Number.isFinite(entry.decodedBodySize) ? Math.round(entry.decodedBodySize) : 0,
        protocol,
        dnsMs: Math.round(dnsMs),
        tcpMs: Math.round(tcpMs),
        tlsMs: Math.round(tlsMs),
        ttfbMs: Math.round(ttfbMs),
        downloadMs: Math.round(downloadMs),
        totalMs: Math.round(totalMs),
      };
    }
  } catch (error) {
    return {
      error: error && error.message ? error.message : String(error),
    };
  }

  return null;
}

function getConnectionDiagnostics() {
  if (typeof navigator === 'undefined' || !navigator || !navigator.connection) {
    return null;
  }

  const connection = navigator.connection;
  return {
    effectiveType: normalizeValue(connection.effectiveType),
    rtt: Number.isFinite(connection.rtt) ? connection.rtt : null,
    downlink: Number.isFinite(connection.downlink) ? connection.downlink : null,
    saveData: Boolean(connection.saveData),
  };
}

function createEmptyStatusCounters() {
  return {
    distributed: 0,
    accepted: 0,
    review: 0,
    done: 0,
    cancelled: 0,
  };
}

function resolveEntryTelegramId(entry) {
  if (!entry || typeof entry !== 'object') {
    return '';
  }
  return normalizeValue(entry.telegram || entry.chatId);
}

const runtimeEnvironment = (() => {
  if (typeof navigator === 'undefined') {
    return {
      userAgent: '',
      platform: '',
      webAppPlatform: '',
      maxTouchPoints: 0,
      isIos: false,
      forceFetchLogging: false,
    };
  }

  const userAgent = typeof navigator.userAgent === 'string' ? navigator.userAgent : '';
  const platform = typeof navigator.platform === 'string' ? navigator.platform : '';
  const maxTouchPoints = typeof navigator.maxTouchPoints === 'number' ? navigator.maxTouchPoints : 0;
  const isIosByUserAgent = /iPad|iPhone|iPod/i.test(userAgent);
  const isTouchMac = /Macintosh/i.test(userAgent) && maxTouchPoints > 1;

  return {
    userAgent,
    platform,
    webAppPlatform: '',
    maxTouchPoints,
    isIos: isIosByUserAgent || isTouchMac,
    forceFetchLogging: false,
  };
})();

const iosDiagnostics = {
  enabled: runtimeEnvironment.isIos,
};

let sharedState = null;
const viewerTabsState = {
  files: [],
  buttons: [],
  activeIndex: 0,
  taskId: null,
  task: null,
  activeFile: null,
  switching: false,
  pendingIndex: null,
  renderedCache: new Map(),
};

const docLoadTracker = {
  startTime: 0,
  stepTimings: [],
  fileName: '',
  fileType: '',
  meta: {},
  timerInterval: null,
  loaderToken: null,
  loaderTransferRenderAt: 0,
  loaderHideTimer: null,
};
const viewerOpenMetrics = {
  sessionOpenId: 0,
  fileAttempts: new Map(),
};

function buildViewerOpenMetricKey(task, file, rawUrl) {
  const taskId = normalizeValue(task && task.id) || '';
  const fileName = normalizeValue(file && file.name) || '';
  const url = normalizeValue(rawUrl) || normalizeValue(file && (file.resolvedUrl || file.previewUrl || file.url)) || '';
  return `${taskId}|${fileName}|${url}`;
}

function getJsMemorySnapshot() {
  if (typeof performance === 'undefined' || !performance || !performance.memory) {
    return null;
  }
  const memory = performance.memory;
  if (!memory || typeof memory.usedJSHeapSize !== 'number') {
    return null;
  }
  return {
    usedJSHeapSize: memory.usedJSHeapSize,
    totalJSHeapSize: typeof memory.totalJSHeapSize === 'number' ? memory.totalJSHeapSize : 0,
    jsHeapSizeLimit: typeof memory.jsHeapSizeLimit === 'number' ? memory.jsHeapSizeLimit : 0,
  };
}

function docLoadStart(fileName, fileType) {
  docLoadTracker.startTime = performance.now();
  docLoadTracker.stepTimings = [];
  docLoadTracker.fileName = fileName || '';
  docLoadTracker.fileType = fileType || '';
  docLoadTracker.meta = {};
}

function docLoadStep(label) {
  if (!docLoadTracker.startTime) return;
  docLoadTracker.stepTimings.push({
    label,
    ms: Math.round(performance.now() - docLoadTracker.startTime),
  });
}

function docLoadFinish(error) {
  if (!docLoadTracker.startTime) return;
  const totalMs = Math.round(performance.now() - docLoadTracker.startTime);
  docLoadStep(error ? 'ошибка' : 'готово');
  const rawMeta = docLoadTracker.meta && typeof docLoadTracker.meta === 'object' ? docLoadTracker.meta : {};
  const docMeta = ensurePdfTimingDiagnostics(rawMeta, rawMeta);
  sendDocLoadLog({
    eventName: 'mini_app_doc_load_timing',
    event: error ? 'load_error' : 'load_complete',
    fileName: docLoadTracker.fileName,
    fileType: docLoadTracker.fileType,
    timings: docLoadTracker.stepTimings,
    totalMs,
    error: error ? (error.message || String(error)) : undefined,
    meta: docMeta,
    source: docMeta.source,
    requestId: docMeta.requestId,
    traceId: docMeta.traceId,
    fetchStartedAt: docMeta.fetchStartedAt,
    responseReceivedAt: docMeta.responseReceivedAt,
    arrayBufferReadyAt: docMeta.arrayBufferReadyAt,
    cacheKey: docMeta.fetchCacheKey || docMeta.cacheKey || '',
    cacheHitArrayBuffer: typeof docMeta.cacheHitArrayBuffer === 'boolean' ? docMeta.cacheHitArrayBuffer : undefined,
    waitedExistingPromise: docMeta.waitedExistingPromise,
    waitedExistingPromiseDurationMs: docMeta.waitedExistingPromiseDurationMs,
    existingPromiseSource: docMeta.existingPromiseSource || '',
    fetchDurationMs: typeof docMeta.fetchDurationMs === 'number' ? docMeta.fetchDurationMs : undefined,
    ttfbMs: docMeta.ttfbMs,
    downloadMs: docMeta.downloadMs,
    responseUrl: docMeta.responseUrl,
    'content-length': docMeta['content-length'] || docMeta.fetchContentLength || '',
    requestStartedAt: typeof docMeta.requestStartedAt === 'number' ? docMeta.requestStartedAt : undefined,
    telegramId: (state && state.telegram && state.telegram.id) ? String(state.telegram.id) : '',
    platform: runtimeEnvironment.webAppPlatform || runtimeEnvironment.platform || '',
    taskFilter: formatTaskFiltersForLog(state && state.taskFilter !== undefined ? state.taskFilter : []),
  });
  docLoadTracker.startTime = 0;
}

function docLoadSetMeta(partialMeta) {
  if (!partialMeta || typeof partialMeta !== 'object' || Array.isArray(partialMeta)) {
    return;
  }
  const normalized = {};
  Object.keys(partialMeta).forEach((key) => {
    if (!key) return;
    const value = partialMeta[key];
    if (value === undefined || value === null || value === '') return;
    normalized[key] = value;
  });
  if (!Object.keys(normalized).length) {
    return;
  }
  docLoadTracker.meta = {
    ...(docLoadTracker.meta && typeof docLoadTracker.meta === 'object' ? docLoadTracker.meta : {}),
    ...normalized,
  };
}

function applyViewerLoaderProgress(loader, progress) {
  if (!(loader instanceof HTMLElement) || typeof progress !== 'number') {
    return;
  }
  const normalized = Math.min(100, Math.max(0, Math.round(progress)));
  loader.dataset.viewerLoaderProgress = String(normalized);
  if (normalized >= 100) {
    loader.dataset.viewerLoaderCompletedAt = String(Date.now());
  } else if (loader.dataset.viewerLoaderCompletedAt) {
    delete loader.dataset.viewerLoaderCompletedAt;
  }
  const barEl = loader.querySelector('[data-viewer-loader-bar]');
  const ringEl = loader.querySelector('[data-viewer-loader-ring]');
  const percentEl = loader.querySelector('[data-viewer-loader-percent]');
  if (barEl instanceof HTMLElement) {
    barEl.style.width = `${normalized}%`;
  }
  if (ringEl && ringEl.style) {
    ringEl.style.strokeDashoffset = String(100 - normalized);
  }
  if (percentEl instanceof HTMLElement) {
    percentEl.textContent = `${normalized}%`;
  }
}

function formatViewerLoaderBytes(bytes) {
  const value = Number(bytes);
  if (!Number.isFinite(value) || value <= 0) {
    return '0 Б';
  }
  if (value < 1024) {
    return `${Math.round(value)} Б`;
  }
  if (value < 1024 * 1024) {
    return `${Math.round(value / 1024)} КБ`;
  }
  const megabytes = value / (1024 * 1024);
  return `${megabytes >= 10 ? Math.round(megabytes) : megabytes.toFixed(1)} МБ`;
}

function formatViewerLoaderDuration(ms) {
  const value = Number(ms);
  if (!Number.isFinite(value) || value <= 0) {
    return 'меньше секунды';
  }
  const seconds = Math.max(1, Math.round(value / 1000));
  if (seconds < 60) {
    return `${seconds} сек`;
  }
  const minutes = Math.floor(seconds / 60);
  const restSeconds = seconds % 60;
  return restSeconds > 0 ? `${minutes} мин ${restSeconds} сек` : `${minutes} мин`;
}

function buildViewerLoaderEstimateText(loader, elapsedMs) {
  if (!(loader instanceof HTMLElement)) {
    return '';
  }
  const progress = Number.parseInt(loader.dataset.viewerLoaderProgress || '0', 10);
  if (!Number.isFinite(progress) || progress <= 0 || progress >= 100 || elapsedMs < 1200) {
    return '';
  }
  const etaMs = (elapsedMs * (100 - progress)) / progress;
  if (!Number.isFinite(etaMs) || etaMs <= 0) {
    return '';
  }
  return `${Math.round(elapsedMs / 1000)} сек · осталось ~${formatViewerLoaderDuration(etaMs)}`;
}

function updateViewerLoaderTransfer(progress, token = docLoadTracker.loaderToken) {
  const loader = document.querySelector('[data-viewer-loader]');
  if (!loader || loader.hidden || (token && docLoadTracker.loaderToken && token !== docLoadTracker.loaderToken)) {
    return;
  }
  const now = Date.now();
  const finished = Boolean(progress && progress.finished);
  if (!finished && now - docLoadTracker.loaderTransferRenderAt < 250) {
    return;
  }
  docLoadTracker.loaderTransferRenderAt = now;

  const loadedBytes = Math.max(0, Number(progress && progress.loadedBytes) || 0);
  const totalBytes = Math.max(0, Number(progress && progress.totalBytes) || 0);
  const startedAt = Number(progress && progress.startedAt) || now;
  const elapsedMs = Math.max(1, now - startedAt);
  const speedBytesPerMs = loadedBytes > 0 ? loadedBytes / elapsedMs : 0;
  const timeEl = loader.querySelector('[data-viewer-loader-time]');
  let text = '';

  if (totalBytes > 0) {
    const percent = Math.min(99, Math.max(0, (loadedBytes / totalBytes) * 100));
    const mappedProgress = Math.min(62, Math.max(45, 45 + (percent * 0.17)));
    applyViewerLoaderProgress(loader, finished ? 62 : mappedProgress);
    const displayLoadedBytes = Math.min(loadedBytes, totalBytes);
    const remainingBytes = Math.max(0, totalBytes - displayLoadedBytes);
    const etaMs = speedBytesPerMs > 0 && remainingBytes > 0 ? remainingBytes / speedBytesPerMs : 0;
    text = `Загружено ${formatViewerLoaderBytes(displayLoadedBytes)} из ${formatViewerLoaderBytes(totalBytes)}`;
    if (!finished && etaMs > 0) {
      text += ` · осталось ~${formatViewerLoaderDuration(etaMs)}`;
    }
  } else {
    const speedText = speedBytesPerMs > 0
      ? ` · скорость ${formatViewerLoaderBytes(speedBytesPerMs * 1000)}/с`
      : '';
    text = `Загружено ${formatViewerLoaderBytes(loadedBytes)}${speedText}`;
  }

  if (timeEl instanceof HTMLElement && text !== '') {
    timeEl.textContent = text;
  }
  loader.dataset.viewerLoaderTransferText = text;
  loader.dataset.viewerLoaderTransferAt = String(now);
}

function sendDocLoadLog(payload) {
  if (!payload || typeof fetch !== 'function') return;
  try {
    const body = JSON.stringify(payload);
    if (typeof navigator !== 'undefined' && typeof navigator.sendBeacon === 'function') {
      const blob = new Blob([body], { type: 'application/json' });
      if (navigator.sendBeacon(DOC_LOAD_LOG_ENDPOINT, blob)) return;
    }
    fetch(DOC_LOAD_LOG_ENDPOINT, {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body,
      credentials: 'include',
      keepalive: true,
    }).catch(() => {});
  } catch (_) { /* ignore */ }
}

function showViewerLoader(fileName) {
  const loader = document.querySelector('[data-viewer-loader]');
  if (!loader) return null;
  const token = `loader_${Date.now().toString(36)}_${Math.random().toString(36).slice(2, 8)}`;
  docLoadTracker.loaderToken = token;
  const titleEl = loader.querySelector('[data-viewer-loader-title]');
  const stepEl = loader.querySelector('[data-viewer-loader-step]');
  const timeEl = loader.querySelector('[data-viewer-loader-time]');
  if (titleEl) titleEl.textContent = fileName ? `Загрузка: ${fileName}` : 'Загрузка документа';
  if (stepEl) stepEl.textContent = 'Подготовка…';
  if (timeEl) timeEl.textContent = '';
  if (docLoadTracker.loaderHideTimer) {
    window.clearTimeout(docLoadTracker.loaderHideTimer);
    docLoadTracker.loaderHideTimer = null;
  }
  loader.dataset.viewerLoaderStartedAt = String(Date.now());
  loader.dataset.viewerLoaderTransferText = '';
  loader.dataset.viewerLoaderTransferAt = '0';
  delete loader.dataset.viewerLoaderCompletedAt;
  docLoadTracker.loaderTransferRenderAt = 0;
  applyViewerLoaderProgress(loader, 0);
  loader.hidden = false;
  const start = performance.now();
  if (docLoadTracker.timerInterval) clearInterval(docLoadTracker.timerInterval);
  docLoadTracker.timerInterval = setInterval(() => {
    if (loader.hidden || docLoadTracker.loaderToken !== token) {
      clearInterval(docLoadTracker.timerInterval);
      docLoadTracker.timerInterval = null;
      return;
    }
    const elapsed = Math.round((performance.now() - start) / 1000);
    if (timeEl) {
      const transferAt = Number.parseInt(loader.dataset.viewerLoaderTransferAt || '0', 10);
      const transferText = loader.dataset.viewerLoaderTransferText || '';
      const elapsedMs = Math.max(0, Math.round(performance.now() - start));
      const estimateText = buildViewerLoaderEstimateText(loader, elapsedMs);
      if (transferText && Number.isFinite(transferAt) && Date.now() - transferAt < 1600) {
        timeEl.textContent = transferText;
      } else if (estimateText) {
        timeEl.textContent = estimateText;
      } else if (elapsed >= 12) {
        timeEl.textContent = `${elapsed} сек · интернет медленный, продолжаем загрузку`;
      } else if (elapsed >= 5) {
        timeEl.textContent = `${elapsed} сек · файл ещё загружается`;
      } else {
        timeEl.textContent = elapsed > 0 ? `${elapsed} сек` : '';
      }
    }
  }, 500);
  return token;
}

function updateViewerLoaderStep(step, progress, token = docLoadTracker.loaderToken) {
  const loader = document.querySelector('[data-viewer-loader]');
  if (!loader || loader.hidden || (token && docLoadTracker.loaderToken && token !== docLoadTracker.loaderToken)) return;
  const stepEl = loader.querySelector('[data-viewer-loader-step]');
  if (stepEl && step) stepEl.textContent = step;
  applyViewerLoaderProgress(loader, progress);
}

function openViewerLoadingShell(previewUrl, fileName, viewerOptions = {}, message = 'Файл загружается...') {
  const viewer = pdfViewerInstance;
  if (!viewer || typeof viewer.open !== 'function' || !previewUrl) {
    return null;
  }

  const loadingOptions = {
    ...viewerOptions,
    isPdf: Boolean(viewerOptions && viewerOptions.isPdf),
    forceCanvas: Boolean(viewerOptions && viewerOptions.forceCanvas),
    skipPdfLoad: true,
    loadingOnly: true,
    loadingMessage: message,
  };

  try {
    return viewer.open(previewUrl, fileName || 'Документ', loadingOptions);
  } catch (_error) {
    return null;
  }
}

function hideViewerLoader(token = docLoadTracker.loaderToken) {
  if (token && docLoadTracker.loaderToken && token !== docLoadTracker.loaderToken) {
    return;
  }
  const loader = document.querySelector('[data-viewer-loader]');
  if (docLoadTracker.loaderHideTimer) {
    window.clearTimeout(docLoadTracker.loaderHideTimer);
    docLoadTracker.loaderHideTimer = null;
  }
  if (loader instanceof HTMLElement && !loader.hidden) {
    const progress = Number.parseInt(loader.dataset.viewerLoaderProgress || '0', 10);
    const completedAt = Number.parseInt(loader.dataset.viewerLoaderCompletedAt || '0', 10);
    const finishDelayMs = 360;
    const elapsedAfterComplete = completedAt > 0 ? Date.now() - completedAt : finishDelayMs;
    if (progress >= 100 && elapsedAfterComplete < finishDelayMs) {
      docLoadTracker.loaderHideTimer = window.setTimeout(() => {
        docLoadTracker.loaderHideTimer = null;
        hideViewerLoader(token);
      }, Math.max(40, finishDelayMs - elapsedAfterComplete));
      return;
    }
  }
  if (loader) {
    loader.hidden = true;
    loader.dataset.viewerLoaderTransferText = '';
    loader.dataset.viewerLoaderTransferAt = '0';
    delete loader.dataset.viewerLoaderCompletedAt;
  }
  if (docLoadTracker.timerInterval) { clearInterval(docLoadTracker.timerInterval); docLoadTracker.timerInterval = null; }
  docLoadTracker.loaderToken = null;
  docLoadTracker.loaderTransferRenderAt = 0;
}

function ensureIosDiagnosticsState(forceEnable = false) {
  if (forceEnable || runtimeEnvironment.isIos) {
    iosDiagnostics.enabled = true;
    runtimeEnvironment.forceFetchLogging = true;
  }
}

function updateEnvironmentFromPlatform(platform) {
  if (!platform || typeof platform !== 'string') {
    return;
  }

  runtimeEnvironment.webAppPlatform = platform;
  const normalized = platform.toLowerCase();
  if (normalized.includes('ios') || normalized.includes('iphone') || normalized.includes('ipad')) {
    runtimeEnvironment.isIos = true;
    ensureIosDiagnosticsState(true);
  }

  syncWebPlatformFlag();
}

function resolveWebPlatformFlag(platformValue) {
  if (!platformValue || typeof platformValue !== 'string') {
    return false;
  }

  const normalized = platformValue.toLowerCase();
  return normalized === 'web' || normalized.includes('web');
}

function getWebPlatformFlag() {
  if (sharedState && sharedState.telegram && sharedState.telegram.platform) {
    return resolveWebPlatformFlag(sharedState.telegram.platform);
  }

  return resolveWebPlatformFlag(runtimeEnvironment.webAppPlatform || '');
}

function getTelegramWebApp() {
  if (typeof window === 'undefined' || !window.Telegram || !window.Telegram.WebApp) {
    return null;
  }

  return window.Telegram.WebApp;
}

function downloadViaTelegramWebApp(url, fileName) {
  const webApp = getTelegramWebApp();
  if (!webApp || typeof webApp.downloadFile !== 'function') {
    return Promise.resolve(false);
  }

  const normalizedUrl = toAbsoluteUrl(url);
  const normalizedName = normalizeValue(fileName) || 'document';
  if (!normalizedUrl || !/^https:\/\//i.test(normalizedUrl)) {
    return Promise.resolve(false);
  }

  return new Promise((resolve) => {
    let settled = false;
    const finish = (success) => {
      if (settled) {
        return;
      }
      settled = true;
      resolve(Boolean(success));
    };

    try {
      const result = webApp.downloadFile({
        url: normalizedUrl,
        file_name: normalizedName,
      }, (accepted) => {
        finish(accepted !== false);
      });

      if (result && typeof result.then === 'function') {
        result.then(() => finish(true)).catch(() => finish(false));
        return;
      }

      window.setTimeout(() => finish(true), 500);
    } catch (error) {
      finish(false);
    }
  });
}

function isTelegramWebAppAvailable() {
  return Boolean(getTelegramWebApp());
}

function isAndroidPlatform() {
  const platform = (sharedState && sharedState.telegram && sharedState.telegram.platform)
    || runtimeEnvironment.webAppPlatform
    || '';
  if (typeof platform === 'string' && platform.toLowerCase().includes('android')) {
    return true;
  }
  const userAgent = runtimeEnvironment.userAgent || '';
  return typeof userAgent === 'string' && userAgent.toLowerCase().includes('android');
}

function isMobileSingleFilePickerPlatform() {
  const platform = String(
    (state && state.telegram && state.telegram.platform)
      || runtimeEnvironment.webAppPlatform
      || runtimeEnvironment.platform
      || '',
  ).toLowerCase();
  if (/(ios|iphone|ipad|android|web)/i.test(platform)) {
    return true;
  }
  const userAgent = String(runtimeEnvironment.userAgent || '').toLowerCase();
  return /(iphone|ipad|ipod|android|mobile)/i.test(userAgent);
}

let isWebPlatform = getWebPlatformFlag();

function syncWebPlatformFlag() {
  isWebPlatform = getWebPlatformFlag();
  if (typeof window !== 'undefined') {
    window.isWebPlatform = isWebPlatform;
  }
}

function updateIosDiagnosticsFromQuery() {
  if (typeof window === 'undefined') {
    ensureIosDiagnosticsState();
    return;
  }

  try {
    const params = new URLSearchParams(window.location.search);
    const debugParam = params.get('ios_debug')
      || params.get('iosdiag')
      || params.get('debug_ios')
      || params.get('enable_ios_logs');

    if (debugParam !== null) {
      const normalized = String(debugParam).trim().toLowerCase();
      if (normalized === '' && runtimeEnvironment.isIos) {
        ensureIosDiagnosticsState(true);
      } else if (['1', 'true', 'yes', 'on', 'debug'].includes(normalized)) {
        ensureIosDiagnosticsState(true);
      }
    } else if (params.has('ioslogs')) {
      ensureIosDiagnosticsState(true);
    }
  } catch (error) {
    // ignore query parsing issues
  }

  ensureIosDiagnosticsState();
}

function annotateEventWithEnvironment(details) {
  if (!details || typeof details !== 'object') {
    return;
  }

  if (runtimeEnvironment.isIos && !Object.prototype.hasOwnProperty.call(details, 'isIos')) {
    details.isIos = true;
  }

  if (iosDiagnostics.enabled && !Object.prototype.hasOwnProperty.call(details, 'iosDiagnosticsEnabled')) {
    details.iosDiagnosticsEnabled = true;
  }

  if (
    iosDiagnostics.enabled
    && !Object.prototype.hasOwnProperty.call(details, 'webAppPlatform')
    && runtimeEnvironment.webAppPlatform
  ) {
    details.webAppPlatform = runtimeEnvironment.webAppPlatform;
  }
}

function shouldUseSendBeacon(keepalive) {
  if (!keepalive || runtimeEnvironment.forceFetchLogging) {
    return false;
  }
  if (sharedState?.telegram?.initData) {
    return false;
  }
  if (typeof navigator === 'undefined' || typeof navigator.sendBeacon !== 'function') {
    return false;
  }
  return true;
}

ensureIosDiagnosticsState();
updateIosDiagnosticsFromQuery();
syncWebPlatformFlag();

function resolveSharedStateForLogging() {
  if (sharedState && typeof sharedState === 'object') {
    return sharedState;
  }
  try {
    if (typeof state !== 'undefined' && state && typeof state === 'object') {
      return state;
    }
  } catch (error) {
    // state может быть недоступен до инициализации
  }
  return null;
}

function sanitizeLogValue(value, depth = 0) {
  if (depth > 3) {
    return '[depth_limit]';
  }

  if (value === null) {
    return null;
  }

  const type = typeof value;
  if (type === 'string' || type === 'number' || type === 'boolean') {
    return value;
  }

  if (type === 'bigint') {
    const numeric = Number(value);
    return Number.isFinite(numeric) ? numeric : value.toString();
  }

  if (type === 'undefined' || type === 'function' || type === 'symbol') {
    return undefined;
  }

  if (value instanceof Date) {
    return value.toISOString();
  }

  if (Array.isArray(value)) {
    const items = [];
    for (let index = 0; index < value.length && index < 20; index += 1) {
      const sanitized = sanitizeLogValue(value[index], depth + 1);
      if (sanitized !== undefined) {
        items.push(sanitized);
      }
    }
    return items.length ? items : undefined;
  }

  if (type === 'object') {
    const result = {};
    Object.keys(value)
      .slice(0, 20)
      .forEach((key) => {
        const sanitized = sanitizeLogValue(value[key], depth + 1);
        if (sanitized !== undefined) {
          result[key] = sanitized;
        }
      });
    return Object.keys(result).length ? result : undefined;
  }

  return String(value);
}

function prepareLogDetails(details) {
  if (details instanceof Error) {
    const summary = {
      name: details.name,
      message: details.message,
    };
    if (typeof details.stack === 'string' && details.stack.trim() !== '') {
      summary.stack = details.stack.split('\n').slice(0, 5).join('\n');
    }
    return prepareLogDetails(summary);
  }

  const sanitized = sanitizeLogValue(details);
  if (sanitized === undefined) {
    return undefined;
  }

  if (Array.isArray(sanitized)) {
    return sanitized.length ? { items: sanitized } : undefined;
  }

  if (sanitized !== null && typeof sanitized === 'object') {
    return sanitized;
  }

  return { value: sanitized };
}

function attachConsoleCapture() {
  // Отключено: sendConsoleLogEntry деактивирована, обёртка console создаёт лишнюю нагрузку
}

function buildClientEventContext() {
  const currentState = resolveSharedStateForLogging();
  if (!currentState) {
    return null;
  }

  const context = {};
  const telegram = currentState.telegram || {};

  if (telegram.id) {
    context.telegramId = String(telegram.id);
  }
  if (telegram.chatId) {
    context.chatId = String(telegram.chatId);
  }
  if (telegram.username) {
    context.telegramUsername = String(telegram.username);
  }
  if (telegram.platform) {
    context.platform = String(telegram.platform);
  } else if (runtimeEnvironment.webAppPlatform) {
    context.platform = runtimeEnvironment.webAppPlatform;
  }
  if (telegram.initDataSummary) {
    context.initDataSummary = telegram.initDataSummary;
  }

  if (currentState.taskFilter !== undefined) {
    context.taskFilter = formatTaskFiltersForLog(currentState.taskFilter);
  }

  if (Array.isArray(currentState.tasks)) {
    context.tasks = currentState.tasks.length;
  }
  if (Array.isArray(currentState.visibleTasks)) {
    context.visibleTasks = currentState.visibleTasks.length;
  }

  if (currentState.stats && typeof currentState.stats === 'object') {
    ['total', 'active', 'completed', 'overdue'].forEach((key) => {
      if (typeof currentState.stats[key] === 'number') {
        context[`stats_${key}`] = currentState.stats[key];
      }
    });
  }

  if (Array.isArray(currentState.organizations) && currentState.organizations.length) {
    const names = [];
    for (let index = 0; index < currentState.organizations.length && names.length < 5; index += 1) {
      const entry = currentState.organizations[index];
      if (typeof entry === 'string') {
        const trimmed = entry.trim();
        if (trimmed) {
          names.push(trimmed);
        }
        continue;
      }
      if (entry && typeof entry === 'object') {
        const candidate = entry.name || entry.title || entry.organization || entry.id || '';
        if (typeof candidate === 'string' && candidate.trim() !== '') {
          names.push(candidate.trim());
        }
      }
    }
    if (names.length) {
      context.organizations = names;
    }
  }

  if (typeof currentState.organizationsChecked === 'number') {
    context.organizationsChecked = currentState.organizationsChecked;
  }

  if (currentState.lastUpdated) {
    context.lastUpdated = String(currentState.lastUpdated);
  }

  if (runtimeEnvironment.userAgent && !context.userAgent) {
    context.userAgent = runtimeEnvironment.userAgent;
  }
  if (runtimeEnvironment.webAppPlatform && !context.webAppPlatform) {
    context.webAppPlatform = runtimeEnvironment.webAppPlatform;
  }

  return Object.keys(context).length ? context : null;
}

function logClientEvent(eventName, details, options) {
  const normalizedEvent = typeof eventName === 'string' ? eventName.trim() : '';
  if (normalizedEvent === '' || !ALLOWED_LOG_EVENTS.has(normalizedEvent)) {
    return false;
  }

  const normalizedDetails = prepareLogDetails(details);
  let finalDetails = normalizedDetails;
  if (normalizedEvent === 'task_view_pdf_diagnostics'
    && normalizedDetails
    && typeof normalizedDetails === 'object'
    && !Array.isArray(normalizedDetails)) {
    const enriched = ensurePdfTimingDiagnostics(normalizedDetails, normalizedDetails);
    if (enriched.details && typeof enriched.details === 'object' && !Array.isArray(enriched.details)) {
      enriched.details = ensurePdfTimingDiagnostics(enriched.details, enriched);
    }
    finalDetails = enriched;
  }
  if (finalDetails && typeof finalDetails === 'object' && !Array.isArray(finalDetails)) {
    annotateEventWithEnvironment(finalDetails);
  }

  const payload = {
    event: normalizedEvent,
    timestamp: new Date().toISOString(),
  };

  if (finalDetails !== undefined) {
    payload.details = finalDetails;
  }

  const context = buildClientEventContext();
  if (context) {
    payload.context = context;
  }

  const keepalive = options && typeof options === 'object' && Object.prototype.hasOwnProperty.call(options, 'keepalive')
    ? Boolean(options.keepalive)
    : true;

  return sendLogPayload(CLIENT_LOG_ENDPOINT, payload, { keepalive });
}

function sendEntryTaskLog(eventName, details, options) {
  return false;
}

function sendDownloadLog(eventName, details, options) {
  const normalizedEvent = typeof eventName === 'string' ? eventName.trim() : '';
  if (normalizedEvent === '' || !DOWNLOAD_LOG_EVENTS.has(normalizedEvent)) {
    return false;
  }
  const platform = getDownloadPlatformType();
  if (platform !== 'android' && platform !== 'ios') {
    return false;
  }

  const normalizedDetails = prepareLogDetails(details);
  if (normalizedDetails && typeof normalizedDetails === 'object' && !Array.isArray(normalizedDetails)) {
    annotateEventWithEnvironment(normalizedDetails);
  }

  const payload = {
    event: normalizedEvent,
    timestamp: new Date().toISOString(),
  };

  if (normalizedDetails !== undefined) {
    payload.details = normalizedDetails;
  }

  const context = buildClientEventContext();
  if (context) {
    payload.context = context;
  }
  payload.platform = platform;

  const keepalive = options && typeof options === 'object' && Object.prototype.hasOwnProperty.call(options, 'keepalive')
    ? Boolean(options.keepalive)
    : true;

  try {
    const body = JSON.stringify(payload);
    if (!body) {
      return false;
    }

    if (shouldUseSendBeacon(keepalive)) {
      const blob = new Blob([body], { type: 'application/json' });
      const sent = navigator.sendBeacon(CLIENT_LOG_ENDPOINT, blob);
      if (sent) {
        return true;
      }
    }

    const requestOptions = {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body,
      credentials: 'include',
    };

    if (keepalive) {
      requestOptions.keepalive = true;
    }

    fetch(CLIENT_LOG_ENDPOINT, requestOptions).catch(() => {});
    return true;
  } catch (error) {
    logViewFlow('sendDownloadLog:fail', error && error.message ? error.message : String(error));
    return false;
  }
}

function sendLogPayload(endpoint, payload, options = {}) {
  if (!endpoint || typeof fetch !== 'function') {
    return false;
  }

  const keepalive = Object.prototype.hasOwnProperty.call(options, 'keepalive')
    ? Boolean(options.keepalive)
    : true;

  try {
    const body = JSON.stringify(payload);
    if (!body) {
      return false;
    }

    if (shouldUseSendBeacon(keepalive)) {
      const blob = new Blob([body], { type: 'application/json' });
      const sent = navigator.sendBeacon(endpoint, blob);
      if (sent) {
        return true;
      }
    }

    const requestOptions = {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body,
      credentials: 'include',
    };

    if (keepalive) {
      requestOptions.keepalive = true;
    }

    fetch(endpoint, requestOptions).catch(() => {});
    return true;
  } catch (error) {
    return false;
  }
}

function logEntryTaskEvent(step, details = {}) {
  const baseDetails = isPlainObject(details) ? { ...details } : { details };
  if (!baseDetails.entryTaskId) {
    baseDetails.entryTaskId = state.entryTaskId || '';
  }
  if (!baseDetails.startParam && state.telegram.startParam) {
    baseDetails.startParam = state.telegram.startParam;
  }
  sendEntryTaskLog(step, baseDetails);
}

function applyEntryTaskId(entryTaskId, source, startParam) {
  const normalized = normalizeValue(entryTaskId);
  if (!normalized) {
    return;
  }
  const isLightTheme = normalizeThemeMode(state.themeMode) === 'light';
  const comboPalette = isLightTheme
    ? {
      optionBg: 'rgba(84, 126, 212, 0.07)',
      optionBorder: 'rgba(94, 136, 219, 0.22)',
      optionColor: '#1d2d4c',
      optionHover: 'rgba(84, 126, 212, 0.16)',
    }
    : {
      optionBg: 'rgba(255, 255, 255, 0.04)',
      optionBorder: 'rgba(141, 181, 255, 0.18)',
      optionColor: '#eff5ff',
      optionHover: 'rgba(123, 173, 255, 0.24)',
    };

  if (!state.entryTaskId) {
    state.entryTaskId = normalized;
  }

  if (startParam && !state.telegram.startParam) {
    state.telegram.startParam = String(startParam).trim();
  }

  if (!state.entryTaskLog || typeof state.entryTaskLog !== 'object') {
    state.entryTaskLog = { resolved: false, matched: false, expanded: false };
  }

  if (!state.entryTaskLog.resolved) {
    logEntryTaskEvent('entry_task_resolved', {
      source: source || 'unknown',
      entryTaskId: normalized,
      startParam: startParam ? String(startParam) : state.telegram.startParam || '',
    });
    state.entryTaskLog.resolved = true;
  }
}

function logAssignmentEvent(step, details = {}) {
  const payload = {
    step: typeof step === 'string' ? step : '',
    ...details,
  };
  logClientEvent('task_assign_debug', payload);
}

function buildErrorDetails(error) {
  const details = {};
  if (error instanceof Error) {
    details.message = error.message;
  } else {
    details.message = String(error);
  }

  if (error && typeof error === 'object') {
    if (Object.prototype.hasOwnProperty.call(error, 'status')) {
      details.status = error.status;
    }
    if (Object.prototype.hasOwnProperty.call(error, 'responseText')) {
      details.responseText = error.responseText;
    }
  }

  return details;
}

function hydrateTelegramFromInitData(initData) {
  if (!initData || typeof initData !== 'string') {
    return;
  }

  let params;
  try {
    params = new URLSearchParams(initData);
  } catch (error) {
    return;
  }

  const userPayload = params.get('user');
  if (userPayload) {
    try {
      const user = JSON.parse(userPayload);
      if (user && typeof user === 'object') {
        if (!state.telegram.id && user.id !== undefined && user.id !== null) {
          state.telegram.id = String(user.id);
        }
        if (!state.telegram.username && typeof user.username === 'string') {
          state.telegram.username = user.username;
        }
        if (!state.telegram.firstName && typeof user.first_name === 'string') {
          state.telegram.firstName = user.first_name;
        }
        if (!state.telegram.lastName && typeof user.last_name === 'string') {
          state.telegram.lastName = user.last_name;
        }
        if (!state.telegram.fullName) {
          const nameParts = [user.first_name, user.last_name]
            .map((part) => (typeof part === 'string' ? part.trim() : ''))
            .filter(Boolean);
          if (nameParts.length) {
            state.telegram.fullName = nameParts.join(' ');
          }
        }
        if (!state.telegram.languageCode && typeof user.language_code === 'string') {
          state.telegram.languageCode = user.language_code;
        }
        if (!state.telegram.photoUrl && typeof user.photo_url === 'string') {
          state.telegram.photoUrl = user.photo_url;
        }
      }
    } catch (error) {
      // ignore JSON parse issues
    }
  }

  const chatType = params.get('chat_type');
  if (!state.telegram.chatType && chatType) {
    state.telegram.chatType = chatType;
  }

  const chatPayload = params.get('chat');
  if (chatPayload) {
    try {
      const chat = JSON.parse(chatPayload);
      if (chat && typeof chat === 'object') {
        if (!state.telegram.chatId && chat.id !== undefined && chat.id !== null) {
          state.telegram.chatId = String(chat.id);
        }
        if (!state.telegram.chatType && typeof chat.type === 'string') {
          state.telegram.chatType = chat.type;
        }
      }
    } catch (error) {
      // ignore malformed chat payloads
    }
  }

  const chatInstance = params.get('chat_instance');
  if (!state.telegram.chatId && chatInstance) {
    state.telegram.chatId = chatInstance;
  }
}


let folders = [
  { id: 'all', name: 'Все задачи', system: true },
  { id: 'no-folder', name: 'Без папки', system: true },
];

let activeFolderId = 'all';
let selectedTaskIds = new Set();
let folderManageMode = false;
let taskFolderMap = {};
let foldersStateJson = '{"folders":[],"taskFolders":{}}';
const DEFAULT_FOLDER_COLOR = '#4d91ff';
const FOLDER_COLOR_PRESETS = [
  '#4d91ff',
  '#16a34a',
  '#f59e0b',
  '#ef4444',
  '#14b8a6',
  '#8b5cf6',
  '#ec4899',
  '#64748b',
];

function normalizeFolderColor(value, fallback = '') {
  const color = normalizeValue(value);
  if (!color) {
    return fallback;
  }
  const normalized = color.trim().toLowerCase();
  return /^#[0-9a-f]{6}$/i.test(normalized) ? normalized : fallback;
}

function loadFoldersFromStorage() {
  try {
    const raw = normalizeValue((typeof window !== 'undefined' && window.__APPDOSC_FOLDERS_JSON__) || foldersStateJson) || '{"folders":[],"taskFolders":{}}';
    const parsedRoot = JSON.parse(raw);
    const parsed = Array.isArray(parsedRoot.folders) ? parsedRoot.folders : [];
    const customFolders = parsed
      .filter((folder) => isPlainObject(folder) && !folder.system && normalizeValue(folder.id) && normalizeValue(folder.name))
      .map((folder) => ({
        id: String(folder.id),
        name: String(folder.name),
        color: normalizeFolderColor(folder.color, DEFAULT_FOLDER_COLOR),
        system: false,
      }));
    folders = [
      { id: 'all', name: 'Все задачи', system: true },
      { id: 'no-folder', name: 'Без папки', system: true },
      ...customFolders,
    ];
  } catch (error) {
    folders = [
      { id: 'all', name: 'Все задачи', system: true },
      { id: 'no-folder', name: 'Без папки', system: true },
    ];
  }
}

function saveFoldersToStorage() {
  try {
    const customFolders = folders.filter((folder) => !folder.system);
    const root = JSON.parse(foldersStateJson || '{"folders":[],"taskFolders":{}}');
    root.folders = customFolders;
    foldersStateJson = JSON.stringify(root);
    if (typeof window !== 'undefined') {
      window.__APPDOSC_FOLDERS_JSON__ = foldersStateJson;
    }
  } catch (error) {}
}

function loadTaskFoldersFromStorage() {
  try {
    const raw = normalizeValue((typeof window !== 'undefined' && window.__APPDOSC_FOLDERS_JSON__) || foldersStateJson) || '{"folders":[],"taskFolders":{}}';
    const parsedRoot = JSON.parse(raw);
    const parsed = parsedRoot && isPlainObject(parsedRoot.taskFolders) ? parsedRoot.taskFolders : {};
    taskFolderMap = isPlainObject(parsed) ? parsed : {};
  } catch (error) {
    taskFolderMap = {};
  }
}

function saveTaskFoldersToStorage() {
  try {
    const map = {};
    state.tasks.forEach((task) => {
      const key = normalizeValue(task && task.id);
      if (!key) return;
      map[key] = normalizeValue(task.folderId) || null;
    });
    taskFolderMap = map;
    const root = JSON.parse(foldersStateJson || '{"folders":[],"taskFolders":{}}');
    root.taskFolders = map;
    foldersStateJson = JSON.stringify(root);
    if (typeof window !== 'undefined') {
      window.__APPDOSC_FOLDERS_JSON__ = foldersStateJson;
    }
  } catch (error) {}
}


function saveState() {
  saveFoldersToStorage();
  saveTaskFoldersToStorage();
}

function extractFoldersFromTasks(tasks) {
  const source = Array.isArray(tasks) ? tasks : [];
  const currentUserId = normalizeValue(state?.telegram?.id);
  if (!currentUserId) return;
  for (let i = 0; i < source.length; i += 1) {
    const task = source[i];
    const settings = isPlainObject(task?.folderSettingsByUser) ? task.folderSettingsByUser : null;
    const userFolders = settings && Array.isArray(settings[currentUserId]) ? settings[currentUserId] : null;
    if (userFolders) {
      const customFolders = userFolders
        .filter((folder) => isPlainObject(folder) && normalizeValue(folder.id) && normalizeValue(folder.name))
        .map((folder) => ({
          id: String(folder.id),
          name: String(folder.name),
          color: normalizeFolderColor(folder.color, DEFAULT_FOLDER_COLOR),
          system: false,
        }));
      folders = [
        { id: 'all', name: 'Все задачи', system: true },
        { id: 'no-folder', name: 'Без папки', system: true },
        ...customFolders,
      ];
      saveFoldersToStorage();
      break;
    }
  }
}

function refreshFolderUi() {
  updateVisibleTasks();
  renderFolders();
  syncTaskSearchControls();
  renderCards();
  renderBulkFolderPanel();
}

function getFolderName(folderId) {
  if (!folderId) return 'Без папки';
  const folder = folders.find((item) => item.id === folderId);
  return folder ? folder.name : 'Без папки';
}

function getFolderById(folderId) {
  const normalizedFolderId = normalizeValue(folderId);
  if (!normalizedFolderId) {
    return null;
  }
  return folders.find((item) => item && item.id === normalizedFolderId) || null;
}

function getFolderColorById(folderId) {
  const folder = getFolderById(folderId);
  if (!folder || folder.system) {
    return '';
  }
  return normalizeFolderColor(folder.color, '');
}

function getFolderColorRgba(color, alpha = 1) {
  const normalizedColor = normalizeFolderColor(color, '');
  if (!normalizedColor) {
    return '';
  }
  const safeAlpha = Math.min(1, Math.max(0, Number.isFinite(Number(alpha)) ? Number(alpha) : 1));
  const red = parseInt(normalizedColor.slice(1, 3), 16);
  const green = parseInt(normalizedColor.slice(3, 5), 16);
  const blue = parseInt(normalizedColor.slice(5, 7), 16);
  return `rgba(${red}, ${green}, ${blue}, ${safeAlpha})`;
}

function normalizeTaskSearchText(value) {
  return normalizeValue(value)
    .toLowerCase()
    .replace(/ё/g, 'е')
    .replace(/[^\p{L}\p{N}]+/gu, ' ')
    .replace(/\s+/g, ' ')
    .trim();
}

function collectTaskSearchTextParts(value, parts, depth = 0) {
  const maxDepth = 6;
  const maxParts = 900;
  const maxItemsPerLevel = 180;
  if (!parts || depth > maxDepth || parts.length >= maxParts || value === null || value === undefined) {
    return;
  }

  if (typeof value === 'string' || typeof value === 'number' || typeof value === 'boolean') {
    const normalized = normalizeValue(value);
    if (normalized) {
      parts.push(normalized);
    }
    return;
  }

  if (Array.isArray(value)) {
    value.slice(0, maxItemsPerLevel).forEach((item) => collectTaskSearchTextParts(item, parts, depth + 1));
    return;
  }

  if (isPlainObject(value)) {
    Object.entries(value)
      .slice(0, maxItemsPerLevel)
      .forEach(([key, item]) => {
        if (TASK_SEARCH_EXCLUDED_FIELD_NAMES.has(key)) {
          return;
        }
        collectTaskSearchTextParts(item, parts, depth + 1);
      });
  }
}

function collectTaskSearchEntryFieldParts(entries, fields, parts) {
  if (!Array.isArray(entries) || !Array.isArray(fields) || !Array.isArray(parts)) {
    return;
  }
  entries.slice(0, 80).forEach((entry) => {
    if (!isPlainObject(entry)) {
      return;
    }
    fields.forEach((field) => {
      if (Array.isArray(entry[field]) || isPlainObject(entry[field])) {
        return;
      }
      const text = normalizeValue(entry[field]);
      if (text) {
        parts.push(text);
      }
    });
  });
}

function collectTaskSearchFileTextParts(task, parts) {
  if (!isPlainObject(task) || !Array.isArray(parts)) {
    return;
  }
  ['files', 'attachments', 'fileList', 'taskFiles'].forEach((field) => {
    const entries = Array.isArray(task[field]) ? task[field] : [];
    collectTaskSearchEntryFieldParts(entries, ['originalName', 'name', 'storedName', 'url', 'ocrText'], parts);
  });
  ['responses', 'answers', 'executorResponses'].forEach((field) => {
    const entries = Array.isArray(task[field]) ? task[field] : [];
    collectTaskSearchEntryFieldParts(entries, ['originalName', 'name', 'storedName', 'url', 'textContent', 'comment', 'note'], parts);
  });
}

function getTaskSearchCollectionCount(task, fields) {
  if (!isPlainObject(task) || !Array.isArray(fields)) {
    return null;
  }
  for (let index = 0; index < fields.length; index += 1) {
    const field = fields[index];
    if (!Object.prototype.hasOwnProperty.call(task, field)) {
      continue;
    }
    const value = task[field];
    if (Array.isArray(value)) {
      return value.length;
    }
    if (isPlainObject(value)) {
      return Object.keys(value).length;
    }
    if (typeof value === 'number' && Number.isFinite(value)) {
      return Math.max(0, Math.round(value));
    }
    if (typeof value === 'string' && /^\d+$/.test(value.trim())) {
      return Math.max(0, Number.parseInt(value.trim(), 10));
    }
  }
  return null;
}

function appendTaskSearchCountPhrases(parts, count, labelSets, zeroPhrases = []) {
  if (!Array.isArray(parts) || !Array.isArray(labelSets)) {
    return;
  }
  const safeCount = Math.max(0, Math.round(Number(count) || 0));
  labelSets.forEach((labelSet) => {
    if (!Array.isArray(labelSet) || labelSet.length < 3) {
      return;
    }
    parts.push(formatPeopleCount(safeCount, labelSet[0], labelSet[1], labelSet[2]));
    parts.push(`количество ${labelSet[2]} ${safeCount}`);
  });
  if (safeCount === 0 && Array.isArray(zeroPhrases)) {
    zeroPhrases.forEach((phrase) => {
      if (phrase) {
        parts.push(phrase);
      }
    });
  }
}

function collectTaskDerivedSearchTextParts(task, parts) {
  if (!isPlainObject(task) || !Array.isArray(parts)) {
    return;
  }
  [
    {
      fields: ['files', 'attachments', 'fileList', 'taskFiles', 'filesCount', 'fileCount', 'attachmentsCount', 'attachmentCount'],
      labels: [['вложение', 'вложения', 'вложений'], ['файл', 'файла', 'файлов']],
      zero: ['без вложений', 'нет вложений', '0 вложений', 'без файлов', 'нет файлов', '0 файлов'],
    },
    {
      fields: ['responses', 'answers', 'executorResponses', 'responseCount', 'responsesCount', 'answersCount'],
      labels: [['ответ', 'ответа', 'ответов'], ['ответ исполнителя', 'ответа исполнителей', 'ответов исполнителей']],
      zero: ['без ответов', 'нет ответов', '0 ответов'],
    },
    {
      fields: ['responsibles', 'assignees', 'executors', 'responsibleProfiles', 'responsibleCount', 'assigneeCount'],
      labels: [['ответственный', 'ответственных', 'ответственных'], ['исполнитель', 'исполнителя', 'исполнителей']],
      zero: ['без ответственных', 'нет ответственных', '0 ответственных'],
    },
    {
      fields: ['subordinates', 'subordinateProfiles', 'subordinateCount'],
      labels: [['подчиненный', 'подчиненных', 'подчиненных'], ['подчинённый', 'подчинённых', 'подчинённых']],
      zero: ['без подчиненных', 'нет подчиненных', '0 подчиненных', 'без подчинённых', 'нет подчинённых', '0 подчинённых'],
    },
  ].forEach((config) => {
    const count = getTaskSearchCollectionCount(task, config.fields);
    if (count === null) {
      return;
    }
    appendTaskSearchCountPhrases(parts, count, config.labels, config.zero);
  });

  [
    { fields: ['instruction', 'resolution', 'assignmentInstruction', 'assignmentComment'], phrases: ['есть поручение', 'с поручением', 'поручение', 'резолюция'] },
    { fields: ['files', 'attachments', 'fileList', 'taskFiles'], phrases: ['есть вложения', 'есть файлы', 'вложения', 'файлы'] },
    { fields: ['responses', 'answers', 'executorResponses'], phrases: ['есть ответы', 'ответы исполнителей', 'ответ исполнителя'] },
    { fields: ['responsibles', 'assignees', 'executors', 'responsibleProfiles', 'executor', 'assignee', 'responsible'], phrases: ['есть ответственный', 'ответственный', 'исполнитель'] },
    { fields: ['subordinates', 'subordinateProfiles'], phrases: ['есть подчиненные', 'подчиненные', 'подчинённые'] },
    { fields: ['correspondent', 'sender', 'author'], phrases: ['корреспондент', 'отправитель', 'от кого'] },
    { fields: ['document', 'summary', 'content', 'description'], phrases: ['тема документа', 'содержание документа', 'описание'] },
  ].forEach((config) => {
    const hasValue = config.fields.some((field) => {
      if (!Object.prototype.hasOwnProperty.call(task, field)) {
        return false;
      }
      const value = task[field];
      if (Array.isArray(value)) {
        return value.length > 0;
      }
      if (isPlainObject(value)) {
        return Object.keys(value).length > 0;
      }
      return normalizeValue(value) !== '';
    });
    if (!hasValue) {
      return;
    }
    config.phrases.forEach((phrase) => parts.push(phrase));
  });
}

function buildTaskSearchHaystack(task) {
  if (!isPlainObject(task)) {
    return '';
  }
  const parts = [];
  collectTaskSearchTextParts(task, parts);
  collectTaskSearchFileTextParts(task, parts);
  collectTaskDerivedSearchTextParts(task, parts);

  return normalizeTaskSearchText(parts.join(' '));
}

function taskMatchesUniversalSearch(task, query) {
  const normalizedQuery = normalizeTaskSearchText(query);
  if (!normalizedQuery) {
    return true;
  }

  const tokens = normalizedQuery.split(' ').filter(Boolean);
  if (!tokens.length) {
    return true;
  }

  const haystack = buildTaskSearchHaystack(task);
  if (!haystack) {
    return false;
  }

  return tokens.every((token) => haystack.includes(token));
}

function normalizeTaskSearchScope(value) {
  const normalized = normalizeValue(value);
  if (!normalized || normalized === TASK_SEARCH_SCOPE_ACTIVE || normalized === TASK_SEARCH_SCOPE_ALL) {
    return normalized || TASK_SEARCH_SCOPE_ACTIVE;
  }
  if (normalized === TASK_SEARCH_SCOPE_NO_FOLDER) {
    return normalized;
  }
  if (normalized.startsWith('folder:')) {
    const folderId = normalized.slice('folder:'.length);
    return ensureActiveFolderId(folderId) === folderId ? normalized : TASK_SEARCH_SCOPE_ACTIVE;
  }
  return TASK_SEARCH_SCOPE_ACTIVE;
}

function resolveTaskSearchFolderId() {
  const scope = normalizeTaskSearchScope(state.activeFilters.searchScope);
  if (scope === TASK_SEARCH_SCOPE_ALL) {
    return 'all';
  }
  if (scope === TASK_SEARCH_SCOPE_NO_FOLDER) {
    return 'no-folder';
  }
  if (scope.startsWith('folder:')) {
    return ensureActiveFolderId(scope.slice('folder:'.length));
  }
  return ensureActiveFolderId(state.activeFilters.folderId || activeFolderId);
}

function getTaskSearchScopeLabel() {
  const scope = normalizeTaskSearchScope(state.activeFilters.searchScope);
  if (scope === TASK_SEARCH_SCOPE_ALL) {
    return 'во всех папках';
  }
  if (scope === TASK_SEARCH_SCOPE_NO_FOLDER) {
    return 'в папке «Без папки»';
  }
  if (scope.startsWith('folder:')) {
    return `в папке «${getFolderName(scope.slice('folder:'.length))}»`;
  }
  return `в текущей папке «${getFolderName(state.activeFilters.folderId || activeFolderId)}»`;
}

function getTaskSearchMetaLabel() {
  const query = normalizeValue(state.activeFilters.searchQuery);
  const visibleCount = getVisibleTaskCount();
  if (query) {
    return `Найдено: ${visibleCount} ${formatTaskCountLabel(visibleCount)} ${getTaskSearchScopeLabel()}`;
  }
  return `Показано: ${visibleCount} ${formatTaskCountLabel(visibleCount)}`;
}

function populateTaskSearchScopeSelect(select, scopeValue) {
  if (!(select instanceof HTMLSelectElement)) {
    return TASK_SEARCH_SCOPE_ACTIVE;
  }

  const scope = normalizeTaskSearchScope(scopeValue);
  select.innerHTML = '';
  select.appendChild(new Option('Все папки', TASK_SEARCH_SCOPE_ALL));
  select.appendChild(new Option('Текущая папка', TASK_SEARCH_SCOPE_ACTIVE));
  select.appendChild(new Option('Без папки', TASK_SEARCH_SCOPE_NO_FOLDER));
  folders
    .filter((folder) => folder && !folder.system)
    .forEach((folder) => select.appendChild(new Option(folder.name, `folder:${folder.id}`)));

  select.value = Array.from(select.options).some((option) => option.value === scope)
    ? scope
    : TASK_SEARCH_SCOPE_ACTIVE;

  return select.value;
}

function syncTaskSearchControls() {
  const query = normalizeValue(state.activeFilters.searchQuery);
  const scope = normalizeTaskSearchScope(state.activeFilters.searchScope);
  state.activeFilters.searchQuery = query;
  state.activeFilters.searchScope = scope;

  const hasQuery = query !== '';

  if (elements.taskSearchInput instanceof HTMLInputElement && elements.taskSearchInput.value !== query) {
    elements.taskSearchInput.value = query;
  }

  if (elements.taskSearchClear instanceof HTMLButtonElement) {
    elements.taskSearchClear.hidden = !hasQuery;
  }

  if (elements.taskSearchScope instanceof HTMLSelectElement) {
    const previousValue = elements.taskSearchScope.value;
    state.activeFilters.searchScope = populateTaskSearchScopeSelect(elements.taskSearchScope, scope);
    if (previousValue && previousValue !== state.activeFilters.searchScope && previousValue === scope) {
      updateVisibleTasks();
    }
  }

  if (elements.taskSearchMeta instanceof HTMLElement) {
    elements.taskSearchMeta.textContent = getTaskSearchMetaLabel();
  }

  if (elements.taskSearchOpen instanceof HTMLElement) {
    elements.taskSearchOpen.setAttribute('aria-pressed', hasQuery ? 'true' : 'false');
    elements.taskSearchOpen.title = hasQuery
      ? `Поиск активен: ${getTaskSearchMetaLabel()}`
      : 'Открыть поиск';
  }

  if (elements.taskSearchCount instanceof HTMLElement) {
    elements.taskSearchCount.hidden = !hasQuery;
    if (hasQuery) {
      elements.taskSearchCount.textContent = String(getVisibleTaskCount());
    }
  }
}

function applyTaskFolderCardAccent(card, task) {
  if (!(card instanceof HTMLElement)) {
    return;
  }
  const folderColor = getFolderColorById(task && task.folderId);
  if (folderColor) {
    card.dataset.folderColor = folderColor;
    card.style.setProperty('--appdosc-folder-task-color', folderColor);
    card.style.setProperty('--appdosc-folder-task-border', getFolderColorRgba(folderColor, 0.48));
    card.style.setProperty('--appdosc-folder-task-ring', getFolderColorRgba(folderColor, 0.14));
    card.style.boxShadow = '';
    card.style.background = '';
    return;
  }

  delete card.dataset.folderColor;
  card.style.removeProperty('--appdosc-folder-task-color');
  card.style.removeProperty('--appdosc-folder-task-border');
  card.style.removeProperty('--appdosc-folder-task-ring');
  card.style.borderColor = '';
  card.style.boxShadow = '';
  card.style.background = '';
}

function updateTaskFolderButtonVisual(button, task) {
  if (!(button instanceof HTMLElement)) {
    return;
  }
  const currentFolderName = getFolderName(task && task.folderId);
  const currentFolderColor = getFolderColorById(task && task.folderId);
  button.dataset.taskId = String((task && task.id) || '');
  button.dataset.folderSelected = currentFolderColor ? 'true' : 'false';
  button.setAttribute('aria-label', `Папка задачи: ${currentFolderName}. Нажмите, чтобы изменить.`);
  button.innerHTML = `
    <span class="task-folder-select__icon" aria-hidden="true">
      <span class="task-folder-select__dot"></span>
    </span>
    <span class="task-folder-select__content">
      <span class="task-folder-select__caption">Папка</span>
      <span class="task-folder-select__value">${escapeHtml(currentFolderName)}</span>
    </span>
    <span class="task-folder-select__chevron" aria-hidden="true">⌄</span>
  `;
  if (currentFolderColor) {
    button.style.setProperty('--task-folder-current-color', currentFolderColor);
    button.style.setProperty('--task-folder-current-soft', getFolderColorRgba(currentFolderColor, 0.12));
    button.style.setProperty('--task-folder-current-border', getFolderColorRgba(currentFolderColor, 0.38));
    button.style.borderColor = getFolderColorRgba(currentFolderColor, 0.4);
    button.style.boxShadow = `0 0 0 1px ${getFolderColorRgba(currentFolderColor, 0.2)} inset`;
  } else {
    button.style.removeProperty('--task-folder-current-color');
    button.style.removeProperty('--task-folder-current-soft');
    button.style.removeProperty('--task-folder-current-border');
    button.style.borderColor = '';
    button.style.boxShadow = '';
  }
}

function setTaskFolder(task, folderId) {
  if (!task || typeof task !== 'object') return;
  task.folderId = normalizeValue(folderId) || null;
}

async function persistTaskFolderToRegistry(task) {
  const organization = normalizeValue(task && task.organization);
  const documentId = normalizeValue(task && (task.id || task.entryNumber || task.registryNumber));
  if (!organization || !documentId) {
    return;
  }
  try {
    await sendTaskMutation({
      updateType: 'folder',
      organization,
      documentId,
      folderId: normalizeValue(task.folderId) || '',
      folderUserId: normalizeValue(state.telegram && state.telegram.id) || '',
    });
  } catch (error) {
    setStatus('error', 'Не удалось сохранить папку в registry.json');
  }
}

async function persistFoldersListToRegistry() {
  const task = Array.isArray(state.tasks) ? state.tasks.find((item) => item && item.organization && item.id) : null;
  if (!task) return;
  try {
    await sendTaskMutation({
      updateType: 'folder_state',
      organization: normalizeValue(task.organization),
      documentId: normalizeValue(task.id),
      folderUserId: normalizeValue(state.telegram && state.telegram.id) || '',
      folderState: folders.filter((item) => !item.system).map((item) => ({
        id: item.id,
        name: item.name,
        color: normalizeFolderColor(item.color, DEFAULT_FOLDER_COLOR),
      })),
    });
  } catch (error) {
    setStatus('error', 'Не удалось сохранить список папок в registry.json');
  }
}
